const express = require('express');
const cors = require('cors');
const cookieParser = require('cookie-parser');
const { initDatabase } = require('./db/InitDb');
const app = express();
app.use(cors({ origin: 'http://localhost:5173', credentials: true }));
app.use(express.json());
app.use(cookieParser());
app.use('/api/auth', require('./routes/authRoutes'));
app.use('/api/projects', require('./routes/projectRoutes'));
app.use('/api/tasks', require('./routes/taskRoutes'));
module.exports = { app, initDatabase };
// server.js
const { app, initDatabase } = require('./app');
require('dotenv').config();
const PORT = process.env.PORT || 3000;
initDatabase().then(() => {
app.listen(PORT, () => console.log(`Server running on port ${PORT}`));
});

// src/api/client.js
const BASE_URL = 'http://localhost:3000/api';
export async function apiRequest(path, options = {}) {
const res = await fetch(`${BASE_URL}${path}`, {
...options,
credentials: 'include',          // sends the HttpOnly cookie
headers: {
'Content-Type': 'application/json',
...options.headers,
},
});
if (!res.ok) {
const error = await res.json().catch(() => ({}));
throw new Error(error.message || `Request failed: ${res.status}`);
}
return res.json();
}
Every component calls this instead of raw fetch() — one place to fix bugs, one place to add auth headers later if needed.

Different ports in dev = different origins, so the browser blocks cookies by default unless you explicitly allow it:
app.use(cors({
origin: 'http://localhost:5173',   // Vite dev server
credentials: true,                  // allow cookies
}));
